package edu.focuslock

import org.json.JSONArray
import org.junit.Assert.assertEquals
import org.junit.Test
import java.io.File

/**
 * Signer test against the shared test_vectors.json generated by Python's sign() in backend/.
 * This guarantees Kotlin's Signer produces byte-identical HMAC-SHA256 signatures to FastAPI's gate.
 */
class SignerTest {

    private fun loadVectors(): JSONArray {
        // Path passed via Gradle systemProperty or fallback to relative path search
        val sysPropPath = System.getProperty("fl.vectors")
        val file = if (!sysPropPath.isNullOrEmpty() && File(sysPropPath).exists()) {
            File(sysPropPath)
        } else {
            // Walk up looking for backend/test_vectors.json
            val candidates = listOf(
                File("../../backend/test_vectors.json"),
                File("../backend/test_vectors.json"),
                File("backend/test_vectors.json")
            )
            candidates.firstOrNull { it.exists() }
                ?: error("Cannot locate test_vectors.json (tried $sysPropPath and relative candidates)")
        }
        return JSONArray(file.readText(Charsets.UTF_8))
    }

    @Test
    fun testAllVectorsMatchPythonSignatures() {
        val vectors = loadVectors()
        assert(vectors.length() >= 3) { "Expected at least 3 test vectors, found ${vectors.length()}" }

        for (i in 0 until vectors.length()) {
            val v = vectors.getJSONObject(i)
            val name = v.getString("name")
            val secret = v.getString("secret")
            val method = v.getString("method")
            val pathWithQuery = v.getString("path_with_query")
            val ts = v.getString("ts")
            val nonce = v.getString("nonce")
            val body = v.getString("body").toByteArray(Charsets.UTF_8)
            val expectedSha = v.getString("body_sha256")
            val expectedSig = v.getString("expected_sig")

            // 1. Verify SHA-256 of body
            val computedSha = Signer.sha256Hex(body)
            assertEquals("SHA256 mismatch for vector $name", expectedSha, computedSha)

            // 2. Verify HMAC-SHA256 signature
            val computedSig = Signer.sign(secret, method, pathWithQuery, ts, nonce, body)
            assertEquals("Signature mismatch for vector $name", expectedSig, computedSig)
        }
    }
}
